    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin-top: 4px;
}

.modal-checkbox {
    width: 18px;
    height: 18px;
    margin-top: 2px;
    accent-color: #558255;
    cursor: pointer;
    flex-shrink: 0;
}

.modal-form-checkbox label {
    font-size: 13px;
    color: #6b7280;
    line-height: 1.5;
    cursor: pointer;
}

.modal-form-checkbox label a {
    color: #558255;
    text-decoration: underline;
}

.modal-form-checkbox label a:hover {
    color: #3d5c3d;
}

.modal-submit-btn {
    width: 100%;
    padding: 16px 24px;
    background: linear-gradient(135deg, #558255 0%, #3d5c3d 100%);
    color: #fff;
    border: none;
    border-radius: 12px;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    transition: all 0.3s ease;
    margin-top: 8px;
    box-shadow: 0 8px 20px rgba(85, 130, 85, 0.3);
    font-family: inherit;
}

.modal-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 28px rgba(85, 130, 85, 0.4);
}

.modal-submit-btn:active {
    transform: translateY(0);
}

.modal-submit-btn svg {
    transition: transform 0.3s ease;
}

.modal-submit-btn:hover svg {
    transform: translateX(4px);
}

/* Сообщение об успехе */
.modal-success {
    text-align: center;
    padding: 30px 20px;
}

.modal-success svg {
    margin: 0 auto 20px;
    display: block;
}

.modal-success h3 {
    font-size: 24px;
    font-weight: 800;
    color: #1a1a1a;
    margin-bottom: 10px;
}

.modal-success p {
    font-size: 15px;
    color: #6b7280;
}

/* Блокировка скролла при открытом модальном окне */
body.modal-open {
    overflow: hidden;
}
